def longest_repeated_substring(s):
    n = len(s)
    longest_substring = ''
    for i in range(n):
        for j in range(i+1, n):
            substring = s[i:j]
            if s.count(substring) > 1 and len(substring) > len(longest_substring):
                longest_substring = substring
    return longest_substring

